std::string EarSourceProcedureView::learnerHistoryExport(){
 if(draftBusy_||mode_!=Mode::Learner||!entry())throw std::runtime_error("Return to learner role and finish the original draft job before exporting");cacheFields();J::Array owners;
 for(const auto&p:entries_){J::Array history,fields;for(const auto&e:p.second->owner->history())history.push_back(e);for(const auto&record:p.second->fields)if(field(record.second,"role")==J("learner"))fields.push_back(record.second);const auto&d=p.second->owner->retainedDefinition();owners.emplace_back(O{{"source_key",p.first},{"source_identity",p.second->identity},{"contract_sha256",d.contractSha256()},{"learner_state",p.second->owner->learnerView()},{"history",history},{"learner_editor_references",fields}});}
 return storage::canonical(O{{"format","fathom-ear-learner-worksheet-v1"},{"selected_source",key_},{"owners",owners},{"observed_performance",false},{"grants_credit",false},{"notice","Native manual submissions and separate learner editor references. Source-role input is redacted by the native history projection; private source forms, provider setup and replay bytes are excluded. Current references follow native reveal rules. No measured hearing, playing, safety, mastery or user acceptance is implied."}});
}
bool EarSourceProcedureView::copyLearnerHistory(){if(draftBusy_)return false;if(mode_!=Mode::Learner||!entry()){fail("Return to an open learner task before copying its worksheet.");return false;}try{const auto bytes=learnerHistoryExport();if(onCopyLearnerHistory)onCopyLearnerHistory(bytes);else{juce::SystemClipboard::copyTextToClipboard(ju(bytes));if(juce::SystemClipboard::getTextFromClipboard().toStdString()!=bytes)throw std::runtime_error("Clipboard readback differs");}fail("Learner worksheet copied. Source setup remains private; editor references are not submitted reports.");return true;}catch(const std::exception&){fail("Worksheet delivery failed. Current work and original reports remain unchanged.");return false;}}

